17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    private final TelephoneNormalizer telephoneNormalizer;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper,
73	                                 TelephoneNormalizer telephoneNormalizer) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	        this.telephoneNormalizer = telephoneNormalizer;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
112	        // A value that cannot form a valid E.164 number is rejected with 400.
113	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        // Store the (already syntactically validated) email lower-cased so it is persisted and
116	        // returned in canonical form. A missing email is left untouched.
117	        owner.setEmail(normalizeEmail(owner.getEmail()));
118	        // Default the registration date to the server's current date when the client did not
119	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
120	        if (owner.getRegistrationDate() == null) {
121	            owner.setRegistrationDate(java.time.LocalDate.now());
122	        }
123	        // Reject creating an owner whose normalized telephone is already used by another owner.
124	        if (isTelephoneInUse(normalizedTelephone)) {
125	            throw new DuplicateTelephoneException(
126	                "An owner with telephone " + normalizedTelephone + " already exists");
127	        }
128	        // Reject creating an owner who shares a household (same last name and address, compared
129	        // case-insensitively with collapsed whitespace) with an existing owner, unless the request
130	        // explicitly opts in with 'sharesHousehold' true.
131	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
132	            && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
133	            throw new DuplicateHouseholdException(
134	                "An owner with the same last name and address already exists");
135	        }
136	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
137	        // equal to one more than the current number of owners, fixed at creation time.
138	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
139	        this.clinicService.saveOwner(owner);
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        headers.setLocation(UriComponentsBuilder.newInstance()
142	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
143	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
144	    }
145	
146	    /**
147	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
148	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
149	     * syntactically valid address (rejecting anything else with 400).
150	     *
151	     * @param email the email value (may be {@code null})
152	     * @return the lower-cased email, or {@code null} if the input was {@code null}
153	     */
154	    private String normalizeEmail(String email) {
155	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
156	    }
157	
158	    /**
159	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
160	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
161	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
162	     *
163	     * @param lastName the owner's last name
164	     * @return the formatted customer code
165	     */
166	    private String nextCustomerCode(String lastName) {
167	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
168	            .toUpperCase(java.util.Locale.ROOT);
169	        int sequence = this.clinicService.findAllOwners().size() + 1;
170	        return String.format("%s-%04d", prefix, sequence);
171	    }
172	
173	    /**
174	     * Determines whether the given normalized telephone is already used by an existing owner.
175	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
176	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
177	     * as the same number.
178	     *
179	     * @param normalizedTelephone the normalized (E.164) telephone to look for
180	     * @return {@code true} if another owner already uses this telephone
181	     */
182	    private boolean isTelephoneInUse(String normalizedTelephone) {
183	        if (normalizedTelephone == null) {
184	            return false;
185	        }
186	        return this.clinicService.findAllOwners().stream()
187	            .map(Owner::getTelephone)
188	            .map(telephoneNormalizer::normalize)
189	            .anyMatch(normalizedTelephone::equals);
190	    }
191	
192	    /**
193	     * Determines whether another owner already shares the given household, i.e. has the same last
194	     * name and the same address. Both fields are compared case-insensitively after collapsing runs
195	     * of whitespace to a single space and trimming, so values that differ only in letter case or in
196	     * incidental spacing are treated as the same household.
197	     *
198	     * @param lastName the last name of the owner being created
199	     * @param address  the address of the owner being created
200	     * @return {@code true} if an existing owner has a matching last name and address
201	     */
202	    private boolean isHouseholdInUse(String lastName, String address) {
203	        String normalizedLastName = normalizeForHousehold(lastName);
204	        String normalizedAddress = normalizeForHousehold(address);
205	        return this.clinicService.findAllOwners().stream()
206	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
207	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
208	    }
209	
210	    /**
211	     * Normalizes a value for household comparison by trimming, collapsing internal runs of
212	     * whitespace to a single space and lower-casing, so comparisons ignore case and incidental
213	     * whitespace differences.
214	     *
215	     * @param value the value to normalize (may be {@code null})
216	     * @return the normalized value, or the empty string if the input was {@code null}
217	     */
218	    private String normalizeForHousehold(String value) {
219	        if (value == null) {
220	            return "";
221	        }
222	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        currentOwner.setAddress(ownerFieldsDto.getAddress());
233	        currentOwner.setCity(ownerFieldsDto.getCity());
234	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
235	        currentOwner.setLastName(ownerFieldsDto.getLastName());
236	        // Normalize the telephone to canonical E.164 form so it is stored and returned
237	        // consistently with create; an unformattable value is rejected with 400.
238	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
239	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
240	        this.clinicService.saveOwner(currentOwner);
241	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Transactional
246	    @Override
247	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        this.clinicService.deleteOwner(owner);
253	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        HttpHeaders headers = new HttpHeaders();
264	        Pet pet = petMapper.toPet(petFieldsDto);
265	        owner.setId(ownerId);
266	        pet.setOwner(owner);
267	        pet.getType().setName(null);
268	        this.clinicService.savePet(pet);
269	        PetDto petDto = petMapper.toPetDto(pet);
270	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
271	            .buildAndExpand(pet.getId()).toUri());
272	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
273	    }
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
278	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
279	        if (currentOwner != null) {
280	            Pet currentPet = this.clinicService.findPetById(petId);
281	            if (currentPet != null) {
282	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
283	                currentPet.setName(petFieldsDto.getName());
284	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
285	                this.clinicService.savePet(currentPet);
286	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	            }
288	        }
289	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
295	        HttpHeaders headers = new HttpHeaders();
296	        Visit visit = visitMapper.toVisit(visitFieldsDto);
297	        Pet pet = new Pet();
298	        pet.setId(petId);
299	        visit.setPet(pet);
300	        this.clinicService.saveVisit(visit);
301	        VisitDto visitDto = visitMapper.toVisitDto(visit);
302	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
303	            .buildAndExpand(visit.getId()).toUri());
304	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
305	    }
306	
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner != null) {
313	            Pet pet = owner.getPet(petId);
314	            if (pet != null) {
315	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
316	            }
317	        }
318	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
319	    }
320	}
