41	    }
42	
43	    public void setFirstName(String firstName) {
44	        this.firstName = firstName;
45	    }
46	
47	    public String getLastName() {
48	        return this.lastName;
49	    }
50	
51	    public void setLastName(String lastName) {
52	        this.lastName = lastName;
53	    }
54	
55	
56	}
