18	
19	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Produces the canonical stored form of an owner's telephone number in E.164.
24	 * <p>
25	 * Centralising this here keeps the REST controllers thin: they simply delegate to
26	 * {@link #normalize(String)} both when canonicalising an incoming value before it is
27	 * persisted and when comparing values to detect duplicates, so the two always agree.
28	 * <p>
29	 * The canonical form is E.164: a leading {@code '+'} and country code are kept when
30	 * present, otherwise country code {@code '+61'} is assumed and a single leading
31	 * {@code '0'} is dropped from the national digits. Spaces, dashes and brackets are
32	 * stripped. The result must carry 8 to 15 digits after the {@code '+'}; anything that
33	 * cannot form valid E.164 is rejected with {@link InvalidTelephoneException} (a 400).
34	 * Because a value already in E.164 form re-normalizes to itself, comparing normalized
35	 * values reliably detects duplicate telephones.
36	 */
37	@Component
38	public class TelephoneNormalizer {
39	
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    /**
43	     * Normalizes the supplied telephone value to its canonical E.164 stored form.
44	     * Spaces, dashes and brackets are stripped; a leading {@code '+'} and country code
45	     * are preserved when present, otherwise {@code '+61'} is assumed and a single leading
46	     * {@code '0'} is dropped from the national digits. Values that differ only in
47	     * formatting therefore normalize to the same result.
48	     *
49	     * @param telephone the raw telephone value (may be {@code null})
50	     * @return the normalized E.164 telephone, or {@code null} if the input was {@code null}
51	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
52	     */
53	    public String normalize(String telephone) {
54	        if (telephone == null) {
55	            return null;
56	        }
57	        boolean hasCountryCode = telephone.trim().startsWith("+");
58	        String digits = telephone.replaceAll("\\D", "");
59	        String nationalOrFull;
60	        if (hasCountryCode) {
61	            nationalOrFull = digits;
62	        } else {
63	            if (digits.startsWith("0")) {
64	                digits = digits.substring(1);
65	            }
66	            nationalOrFull = DEFAULT_COUNTRY_CODE + digits;
67	        }
68	        if (!nationalOrFull.matches("\\d{8,15}")) {
69	            throw new InvalidTelephoneException(
70	                "Telephone '" + telephone + "' cannot be normalized to a valid E.164 number");
71	        }
72	        return "+" + nationalOrFull;
73	    }
74	}
